ems:center;gap:7px;min-height:32px;font-size:11px}.check input{width:auto;min-height:auto}.form-actions{display:flex;align-items:end;justify-content:flex-end;gap:8px;margin-top:18px;padding:14px 16px 18px;border-top:1px solid #e8edf4}.reason{width:min(420px,55%);margin-bottom:0}.message{margin-right:auto;color:#176b35;font-size:11px}.message.error{color:#b42318}.price-box{grid-column:1/-1;margin-top:8px;border:1px solid #dfe7f1;border-radius:5px;overflow:hidden}.price-box-head{padding:10px 12px;background:#f7f9fc;border-bottom:1px solid #dfe7f1;display:flex;justify-content:space-between;align-items:center}.price-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding:11px 12px;border-bottom:1px solid #e8edf4}.price-form .reason-price{grid-column:1/4;margin-bottom:10px}.price-form .price-save{align-self:end;margin-bottom:10px}.price-table{width:100%;border-collapse:collapse}.price-table th,.price-table td{padding:7px 8px;border-bottom:1px solid #edf1f6;text-align:left;font-size:10px}.price-table th{background:#fafbfd;color:#64748b}.price-current{font-weight:800;color:#075ecf}.price-future{color:#9a6700}.history{width:100%;border-collapse:collapse}.history th,.history td{padding:8px;border-bottom:1px solid #edf1f6;text-align:left;vertical-align:top;font-size:10px}.history th{background:#f7f9fc;color:#64748b}.change-values{max-width:360px;white-space:normal;word-break:break-word;color:#475569}.detail-empty{padding:70px 20px}.specific-fields{display:contents}@media(max-width:1180px){.layout{grid-template-columns:1fr}.list-card{max-height:500px}.detail-card{position:static;max-height:none}}@media(max-width:720px){main{padding:8px}.filters,.form-grid,.price-form{grid-template-columns:1fr}.wide,.two,.price-form .reason-price{grid-column:auto}.reason{width:100%}.form-actions{padding:12px 14px 16px}.products{min-width:580px}.table-scroll{overflow:auto}}
