  <script>
    const canEdit=@json($canEdit),canChangePrice=@json($canChangePrice),state={page:1,lastPage:1,selectedId:null,isNew:false,dirty:false,priceRules:[]};
    const el=id=>document.getElementById(id),csrf=document.querySelector('meta[name="csrf-token"]').content;
    const api=async(url,options={})=>{const response=await fetch(url,{credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},...options});const body=await response.json().catch(()=>({}));if(!response.ok){const errors=body.errors?Object.values(body.errors).flat().join(' / '):null;throw new Error(errors||body.message||body.error?.message||'処理に失敗しました。')}return body.data};
    const msg=(text,error=false)=>{el('form-message').textContent=text;el('form-message').classList.toggle('error',error)};
    const number=value=>value===null||value===''?'':Number(value).toLocaleString('ja-JP',{maximumFractionDigits:4});
    const yen=value=>'¥'+Number(value||0).toLocaleString('ja-JP',{maximumFractionDigits:0});
    const value=id=>el(id).value.trim(),nullable=id=>value(id)||null,numeric=id=>value(id)===''?null:Number(value(id)),idOrNull=id=>value(id)===''?null:Number(value(id));
    const query=(page=true)=>{const p=new URLSearchParams();const values={q:value('filter-q'),capacity:value('filter-capacity'),category:value('filter-category'),active:value('filter-active')};Object.entries(values).forEach(([key,val])=>val&&p.set(key,val));if(page){p.set('page',state.page);p.set('per_page','30')}return p};
    const setFilterDirty=dirty=>el('filters')?.querySelector('button[type="submit"]')?.classList.toggle('search-attention',dirty);
    async function loadList(){try{setFilterDirty(false);const data=await api(`/api/v1/masters/products?${query()}`);state.lastPage=data.pagination.last_page;renderList(data.products,data.pagination);el('export-csv').href=`/api/v1/masters/products/export?${query(false)}`}catch(error){msg(error.message,true)}}
    function renderList(items,pagination){const body=el('product-list');body.replaceChildren(...items.map(item=>{const row=document.createElement('tr');row.classList.toggle('selected',String(item.id)===String(state.selectedId));row.innerHTML='<td><span class="code"></span></td><td><div class="product-name"></div><span class="muted"></span></td><td></td><td></td>';row.children[0].firstChild.textContent=item.product_code;row.children[1].firstChild.textContent=item.display_name||item.name;row.children[1].lastChild.textContent=item.category_name||'未分類';row.children[2].textContent=[number(item.capacity_value),item.capacity_unit_name].filter(Boolean).join(' ');row.children[3].innerHTML=`<span class="status${item.is_active?'':' inactive'}">${item.is_active?'有効':'無効'}</span>`;row.onclick=()=>selectProduct(item.id);return row}));el('empty-list').hidden=items.length>0;el('result-count').textContent=`${pagination.total.toLocaleString()}件`;el('page-info').textContent=`${pagination.current_page} / ${Math.max(1,pagination.last_page)}ページ`;el('prev-page').disabled=pagination.current_page<=1;el('next-page').disabled=pagination.current_page>=pagination.last_page}
    async function selectProduct(id){if(state.dirty&&!confirm('保存していない変更があります。破棄しますか？'))return;state.selectedId=id;state.isNew=false;await loadProduct();await loadList()}
    async function loadProduct(){try{const data=await api(`/api/v1/masters/products/${state.selectedId}`);fill(data.product);showForm();msg('')}catch(error){msg(error.message,true)}}
    function showForm(){el('detail-empty').hidden=true;el('product-form').hidden=false;el('reload-product').disabled=state.isNew;el('reason-label').hidden=state.isNew;state.dirty=false}
    function newProduct(){if(state.dirty&&!confirm('保存していない変更があります。破棄しますか？'))return;state.selectedId=null;state.isNew=true;state.priceRules=[];el('product-form').reset();el('product-code').disabled=false;el('sales-available').checked=true;el('inventory-managed').checked=true;el('is-active').checked=true;renderPrices();renderHistory([]);toggleSpecific();el('detail-title').textContent='新しい商品';el('detail-subtitle').textContent='商品単位で登録します。';showForm();activateTab('basic')}
    function fill(product){el('detail-title').textContent=product.display_name;el('detail-subtitle').textContent=product.product_code;el('product-code').value=product.product_code;el('product-code').disabled=false;el('name').value=product.name||'';el('name-kana').value=product.name_kana||'';el('display-name').value=product.display_name||'';el('category-name').value=product.category_name||'';el('product-type').value=product.product_type;el('tax-category').value=product.consumption_tax_category_id||'';el('sales-available').checked=product.is_sales_available;el('inventory-managed').checked=product.is_inventory_managed;el('is-active').checked=product.is_active;el('note').value=product.note||'';el('capacity-value').value=product.capacity_value??'';el('capacity-unit').value=product.capacity_unit_id||'';el('base-unit').value=product.base_unit_id||'';el('sales-unit').value=product.sales_unit_id||'';el('inventory-unit').value=product.inventory_unit_id||'';el('alcohol').value=product.alcohol_percentage??'';el('liquor-tax-code').value=product.liquor_tax_category_code||'';el('liquor-type-name').value=product.liquor_type_name||'';el('polishing').value=product.rice_polishing_ratio??'';el('ingredients').value=product.ingredients||'';el('production-method').value=product.production_method||'';el('unpasteurized').checked=product.is_unpasteurized;el('kasu-type').value=product.kasu_type||'';el('kasu-storage').value=product.storage_method||'';el('food-category').value=product.food_category||'';el('food-storage').value=product.storage_method||'';el('shelf-life').value=product.shelf_life_days??'';el('allergen-note').value=product.allergen_note||'';el('goods-category').value=product.goods_category||'';el('material').value=product.material||'';el('size-description').value=product.size_description||'';el('change-reason').value='';state.priceRules=product.price_rules||[];toggleSpecific();renderPrices();renderHistory(product.history||[]);state.dirty=false}
    function payload(){return{product_code:value('product-code'),product_type:value('product-type'),name:value('name'),name_kana:nullable('name-kana'),display_name:value('display-name'),category_name:nullable('category-name'),consumption_tax_category_id:Number(value('tax-category')),base_unit_id:Number(value('base-unit')),sales_unit_id:idOrNull('sales-unit'),inventory_unit_id:idOrNull('inventory-unit'),capacity_value:numeric('capacity-value'),capacity_unit_id:idOrNull('capacity-unit'),alcohol_percentage:numeric('alcohol'),liquor_tax_category_code:nullable('liquor-tax-code'),liquor_type_name:nullable('liquor-type-name'),ingredients:nullable('ingredients'),rice_polishing_ratio:numeric('polishing'),production_method:nullable('production-method'),is_unpasteurized:el('unpasteurized').checked,kasu_type:nullable('kasu-type'),food_category:nullable('food-category'),allergen_note:nullable('allergen-note'),storage_method:value('product-type')==='food'?nullable('food-storage'):nullable('kasu-storage'),shelf_life_days:numeric('shelf-life'),goods_category:nullable('goods-category'),material:nullable('material'),size_description:nullable('size-description'),is_sales_available:el('sales-available').checked,is_inventory_managed:el('inventory-managed').checked,is_active:el('is-active').checked,note:nullable('note'),change_reason:state.isNew?'商品登録':value('change-reason')||null}}
    async function saveProduct(event){event.preventDefault();msg('保存中です。');try{const endpoint=state.isNew?'/api/v1/masters/products':`/api/v1/masters/products/${state.selectedId}`;const data=await api(endpoint,{method:state.isNew?'POST':'PUT',body:JSON.stringify(payload())});state.selectedId=data.product.id;state.isNew=false;fill(data.product);await loadList();msg('商品を保存しました。')}catch(error){msg(error.message,true)}}
    function toggleSpecific(){const type=value('product-type');['sake','kasu','food','goods'].forEach(name=>el(`${name}-fields`).hidden=name!==type)}
    function renderPrices(){const today=new Date().toISOString().slice(0,10),showPast=el('show-past-prices').checked;const items=state.priceRules.filter(item=>showPast||(item.is_active&&(!item.effective_to||item.effective_to>=today)));const body=el('price-list');body.replaceChildren(...items.map(item=>{const row=document.createElement('tr');const period=`${item.effective_from||'-'} ～ ${item.effective_to||''}`,future=item.effective_from>today,ended=!item.is_active||(item.effective_to&&item.effective_to<today);row.innerHTML='<td></td><td></td><td></td><td></td><td></td><td></td><td></td>';row.children[0].textContent=item.price_type_name;row.children[1].textContent=yen(item.unit_price);row.children[1].className='price-current';row.children[2].textContent=item.price_type==='retail'?yen(item.tax_included_unit_price):'-';row.children[3].textContent=period;row.children[3].classList.toggle('price-future',future);row.children[4].textContent=item.unit_name||'-';row.children[5].textContent=ended?'終了':(future?'予定':'有効');if(canChangePrice&&!ended){const button=document.createElement('button');button.type='button';button.className='danger';button.textContent='無効化';button.onclick=()=>deactivatePrice(item.id);row.children[6].appendChild(button)}return row}));el('price-empty').hidden=items.length>0}
    async function savePrice(){if(!state.selectedId)return msg('商品を先に保存してください。',true);const body={price_type:value('price-type'),unit_id:Number(value('price-unit')),unit_price:value('price-value'),effective_from:value('price-from'),effective_to:nullable('price-to'),reason:value('price-reason')};try{await api(`/api/v1/masters/products/${state.selectedId}/price-revisions`,{method:'POST',body:JSON.stringify(body)});await loadProduct();activateTab('price');msg('新しい価格を登録しました。')}catch(error){msg(error.message,true)}}
    async function deactivatePrice(id){const reason=prompt('価格を無効化する理由を入力してください。');if(!reason)return;try{await api(`/api/v1/masters/products/${state.selectedId}/price-rules/${id}/deactivate`,{method:'POST',body:JSON.stringify({reason})});await loadProduct();msg('価格を無効化しました。')}catch(error){msg(error.message,true)}}
    function renderHistory(items){const body=el('history-list');body.replaceChildren(...items.map(item=>{const row=document.createElement('tr');const changes=[];const before=item.before_values||{},after=item.after_values||{};Object.keys({...before,...after}).forEach(key=>{if(JSON.stringify(before[key])!==JSON.stringify(after[key]))changes.push(`${key}: ${before[key]??'-'} → ${after[key]??'-'}`)});[item.occurred_at?new Date(item.occurred_at).toLocaleString('ja-JP'):'-',item.user_name||'-',item.event||'-',changes.join(' / ')||'-',item.reason||'-'].forEach((text,index)=>{const cell=document.createElement('td');cell.textContent=text;if(index===3)cell.className='change-values';row.appendChild(cell)});return row}));el('history-empty').hidden=items.length>0}
    function activateTab(name){document.querySelectorAll('.tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.tab===name));document.querySelectorAll('[data-panel]').forEach(panel=>panel.hidden=panel.dataset.panel!==name);el('product-actions').hidden=['price','history'].includes(name)}
    el('filters').onsubmit=event=>{event.preventDefault();state.page=1;loadList()};el('filters').addEventListener('input',()=>setFilterDirty(true));el('filters').addEventListener('change',()=>setFilterDirty(true));el('clear-filter').onclick=()=>{el('filters').reset();state.page=1;loadList()};el('prev-page').onclick=()=>{if(state.page>1){state.page--;loadList()}};el('next-page').onclick=()=>{if(state.page<state.lastPage){state.page++;loadList()}};el('new-product')?.addEventListener('click',newProduct);el('reload-product').onclick=()=>state.selectedId&&loadProduct();el('product-form').onsubmit=saveProduct;el('product-type').onchange=toggleSpecific;el('show-past-prices').addEventListener('change',renderPrices);el('save-price')?.addEventListener('click',savePrice);document.querySelectorAll('.tab').forEach(tab=>tab.onclick=()=>activateTab(tab.dataset.tab));el('product-form').addEventListener('input',event=>{if(!event.target.closest('[data-panel="price"]'))state.dirty=true});window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue=''}});loadList();
  </script>
</body>
</html>
